1. import { useQuery } from "@tanstack/react-query";
2. import { useQueryParams } from "raviger";
3. import { useEffect } from "react";
4. import { useTranslation } from "react-i18next";
5. import { toast } from "sonner";
6. 
7. import { cn } from "@/lib/utils";
8. 
9. import { Button } from "@/components/ui/button";
10. 
11. import PaginationComponent from "@/components/Common/Pagination";
12. import { CardListSkeleton } from "@/components/Common/SkeletonLoading";
13. import CreateEncounterForm from "@/components/Encounter/CreateEncounterForm";
14. import { TimelineEncounterCard } from "@/components/Facility/EncounterCard";
15. import { PatientProps } from "@/components/Patient/PatientDetailsTab";
16. 
17. import { getPermissions } from "@/common/Permissions";
18. 
19. import { ShortcutBadge } from "@/Utils/keyboardShortcutComponents";
20. import query from "@/Utils/request/query";
21. import { goBack } from "@/Utils/utils";
22. import { TimelineWrapper } from "@/components/Common/TimelineWrapper";
23. import { EmptyState } from "@/components/ui/empty-state";
24. import { usePermissions } from "@/context/PermissionContext";
25. import { useShortcutSubContext } from "@/context/ShortcutContext";
26. import encounterApi from "@/types/emr/encounter/encounterApi";
27. import { CaptionsOff, PlusIcon } from "lucide-react";
28. 
29. const EncounterHistory = (props: PatientProps) => {
30.   const { patientData, facilityId } = props;
31.   const patientId = patientData.id;
32.   useShortcutSubContext("facility:patient:home");
33. 
34.   const { t } = useTranslation();
35. 
36.   const [qParams, setQueryParams] = useQueryParams<{ page?: number }>();
37.   const { hasPermission } = usePermissions();
38.   const { canViewPatients } = getPermissions(
39.     hasPermission,
40.     patientData.permissions,
41.   );
42. 
43.   const { data: encounterData, isLoading } = useQuery({
44.     queryKey: ["encounterHistory", patientId, qParams],
45.     queryFn: query(encounterApi.list, {
46.       queryParams: {
47.         patient: patientId,
48.         limit: 5,
49.         offset: ((qParams.page || 1) - 1) * 5,
50.       },
51.     }),
52.     enabled: canViewPatients,
53.   });
54. 
55.   useEffect(() => {
56.     if (!canViewPatients) {
57.       toast.error(t("no_permission_to_view_page"));
58.       goBack(`/facility/${facilityId}/patient/${patientId}`);
59.     }
60.     // eslint-disable-next-line react-hooks/exhaustive-deps
61.   }, [canViewPatients]);
62. 
63.   return (
64.     <div className="mt-8">
65.       <div>
66.         {isLoading ? (
67.           <div>
68.             <div className="grid gap-5">
69.               <CardListSkeleton count={5} />
70.             </div>
71.           </div>
72.         ) : (
73.           <div>
74.             {encounterData?.results?.length === 0 ? (
75.               facilityId ? (
76.                 <div className="p-2">
77.                   <EmptyState
78.                     title={t("no_active_encounters_found")}
79.                     description={t("create_a_new_encounter_to_get_started")}
80.                     icon={<CaptionsOff className="size-5 text-primary m-1" />}
81.                     action={
82.                       <CreateEncounterForm
83.                         facilityId={facilityId}
84.                         patientId={patientId}
85.                         patientName={patientData.name}
86.                         trigger={
87.                           <Button>
88.                             <PlusIcon />
89.                             {t("create_encounter")}
90.                             <ShortcutBadge actionId="create-encounter" />
91.                           </Button>
92.                         }
93.                       />
94.                     }
95.                   />
96.                 </div>
97.               ) : (
98.                 <div className="p-2">
99.                   <div className="h-full space-y-2 rounded-lg bg-white px-7 py-12 border border-secondary-300">
100.                     <div className="flex w-full items-center justify-center text-lg text-secondary-600">
101.                       <div className="h-full flex w-full items-center justify-center">
102.                         <span className="text-sm text-gray-500">
103.                           {t("no_encounters_found")}
104.                         </span>
105.                       </div>
106.                     </div>
107.                   </div>
108.                 </div>
109.               )
110.             ) : (
111.               <ul className="grid gap-4">
112.                 <TimelineWrapper>
113.                   {encounterData?.results?.map((encounter) => (
114.                     <li key={encounter.id} className="w-full">
115.                       <TimelineEncounterCard
116.                         key={encounter.id}
117.                         encounter={encounter}
118.                         permissions={patientData.permissions ?? []}
119.                         facilityId={facilityId}
120.                       />
121.                     </li>
122.                   ))}
123.                 </TimelineWrapper>
124.                 <div className="flex w-full items-center justify-center">
125.                   <div
126.                     className={cn(
127.                       "flex w-full justify-center",
128.                       (encounterData?.count ?? 0) > 5 ? "visible" : "invisible",
129.                     )}
130.                   >
131.                     <PaginationComponent
132.                       cPage={qParams.page || 1}
133.                       defaultPerPage={5}
134.                       data={{ totalCount: encounterData?.count ?? 0 }}
135.                       onChange={(page) => setQueryParams({ page })}
136.                     />
137.                   </div>
138.                 </div>
139.               </ul>
140.             )}
141.           </div>
142.         )}
143.       </div>
144.     </div>
145.   );
146. };
147. 
148. export default EncounterHistory;
149.

