18. interface ApiListResponse<T> {
19.   results: T[];
20. }
21. 
22. async function api<T>(
23.   path: string,
24.   init?: { method?: string; body?: unknown },
25. ): Promise<T> {
26.   const response = await fetch(`${getApiUrl()}${path}`, {
27.     method: init?.method ?? "GET",
28.     headers: getApiHeaders(),
29.     body: init?.body ? JSON.stringify(init.body) : undefined,
30.   });
31.   if (!response.ok) {
32.     throw new Error(
33.       `${init?.method ?? "GET"} ${path} failed: ${response.status} — ${await response.text()}`,
34.     );
35.   }
36.   return (await response.json()) as T;
37. }
