39. async function getGeoOrganizationId(): Promise<string> {
40.   const { results } = await api<ApiListResponse<{ id: string }>>(
41.     "/api/v1/organization/?org_type=govt&limit=1",
42.   );
43.   const id = results[0]?.id;
44.   if (!id) throw new Error("No govt organization found");
