48. async function getRoleId(name: string): Promise<string> {
49.   const { results } = await api<ApiListResponse<{ id: string; name: string }>>(
50.     `/api/v1/role/?name=${encodeURIComponent(name)}`,
51.   );
52.   const role = results.find((item) => item.name === name);
53.   if (!role) throw new Error(`Role not found: ${name}`);
54.   return role.id;
55. }
