75. 
76.   const { results } = await api<
77.     ApiListResponse<{
78.       id: string;
79.       user: { id: string };
80.       role: { id: string };
81.     }>
82.   >(`${path}?limit=100`);
83.   const existing = results.find((item) => item.user.id === userId);
84. 
85.   if (!existing) {
86.     await api(path, { method: "POST", body: { user: userId, role: roleId } });
87.     return;
